// HasBackgroundTask applies the HasEdge predicate on the "background_task" edge.
func HasBackgroundTask() predicate.DingTalkDirectorySync {
	return predicate.DingTalkDirectorySync(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2O, true, BackgroundTaskTable, BackgroundTaskColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasBackgroundTaskWith applies the HasEdge predicate on the "background_task" edge with a given conditions (other predicates).
func HasBackgroundTaskWith(preds ...predicate.BackgroundTask) predicate.DingTalkDirectorySync {
	return predicate.DingTalkDirectorySync(func(s *sql.Selector) {
		step := newBackgroundTaskStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

